export const VERBAL_EDITORIAL_SCENE_IDS_V52=Object.freeze(Object.keys(rows));

export function verbalEditorialLineV52({event,target,phase='event'}={}){
 const entry=rows[event?.id];
 if(!entry)return null;
 const visibleSpeaker=event?.speaker||'wing';
 if(visibleSpeaker!==entry.speaker||(target||visibleSpeaker)!==entry.speaker)return null;
 return entry[phase==='result'?'result':'event'];
}
